namespace HankModPack;

/// <summary>The theme textures (560x300 RGB tiles, deflated, base64) kept as plain source so the mod needs no embedded resource. Generated by an offline script.</summary>
static partial class TexData
{
    public static string? Get(string name) => name switch
    {
        "steel" => string.Concat(Steel),
        "wood" => string.Concat(Wood),
        "wool" => string.Concat(Wool),
        "winter" => string.Concat(Winter),
        "summer" => string.Concat(Summer),
        _ => null,
    };
}
